using System;
using System.IO;
using System.Collections.Generic;
class PassengerOverridesTests {
 static int n;static void Check(bool x,string why){n++;if(!x)throw new Exception(why);}static void Reject(Action a,string why){bool rejected=false;try{a();}catch(ArgumentException){rejected=true;}Check(rejected,why);}
 static string Wrap(string pool,string traits,string rows){return "{\"version\":2,\"presets\":[{\"id\":\"custom\",\"name\":\"custom\",\"enabled\":true,\"weight\":1,\"pool\":\""+pool+"\",\"traits\":["+traits+"],\"intro\":\"\",\"overrides\":["+rows+"]}]}";}
 static string Row(string id,string value){return ContentJson.Stringify(new Dictionary<string,object>{{"id",id},{"value",value}});}
 static string Profile(string json){var p=ContentJson.Object(ContentJson.Parse(ContentTuning.CaptureJson()));foreach(object o in ContentJson.Array(p["values"])){var r=ContentJson.Object(o);if((string)r["id"]=="passenger.presets")r["value"]=json;}p["contentHash"]=ContentTuning.ComputeHash(p);return ContentJson.Stringify(p);}
 static PassengerBehaviorState Make(string pool,string traits,string rows){ContentTuning.UseJson(Profile(Wrap(pool,traits,rows)));return PassengerBehaviorState.CreateConfigured("same-seed",(PassengerType)Enum.Parse(typeof(PassengerType),pool),null,null);}
 static void Main(string[] args){try{Run(args);Console.WriteLine("PASS PassengerOverridesTests "+n);}catch(Exception e){Console.WriteLine("FAIL "+e.Message);Environment.Exit(1);}}
 static void Run(string[] args){ContentTuning.ConfigureCatalog(File.ReadAllText(args[0]));string baseline=ContentTuning.CaptureJson();
  foreach(object o in ContentJson.Array(ContentJson.Object(ContentJson.Parse(File.ReadAllText(args[1])))["cases"])){var row=ContentJson.Object(o);bool valid=true;try{PassengerPresetCatalog.Parse(ContentJson.Stringify(row["data"]));}catch(ArgumentException){valid=false;}Check(valid==(bool)row["valid"],"shared "+row["name"]);}
  var dry=Make("Food","\"item.food\"",Row("effect.food.spillPercent","0")+","+Row("effect.food.crumbs","2")+","+Row("choice.type.Food.1.immediate.satisfaction","1"));
  var wet=Make("Food","\"item.food\"",Row("effect.food.spillPercent","100")+","+Row("effect.food.crumbs","9")+","+Row("choice.type.Food.1.immediate.satisfaction","7"));
  Check(Object.ReferenceEquals(dry.Content,dry.Content),"rider resolver reused across frame reads");ContentTuning.UseJson(baseline);Check(!dry.SpillPlanned&&wet.SpillPlanned,"same-seed probability frozen per rider zero/100");
  foreach(var p in new[]{dry,wet}){p.Board();p.Respond(1,true);p.Advance(30,false,true,.6f,100);p.Validate();}
  Check(dry.DirtEvents[0].Amount==2&&wet.DirtEvents[0].Amount==9,"interleaved riders retain individual dirt");
  var ledger=new ChoiceEffectLedger();Check(ledger.Select("rider-choice",ChoiceEffectDefinition.Read("type.Food.1",wet.Content),50,20).satisfaction==7,"resolved ledger immediate7");ledger.Validate(wet.Content);Reject(()=>ledger.Validate(dry.Content),"restore rejects other rider effect definition");Check(ChoiceEffectDefinition.Read("type.Food.1",dry.Content).immediate.satisfaction==1,"next rider effect1 no leak");
  var copy=wet.Copy();copy.PresetOverrides[0].value="0";Check(wet.Content.Int("effect.food.spillPercent",-1)==100,"saved overrides deep copy");
  var quick=Make("Luggage","\"item.luggage\"",Row("effect.luggage.prepareSeconds","3"));var slow=Make("Luggage","\"item.luggage\"",Row("effect.luggage.prepareSeconds","17"));ContentTuning.UseJson(baseline);quick.Respond(0,true);slow.Respond(0,true);quick.Advance(3,true,false,0,100);slow.Advance(3,true,false,0,100);Check(quick.BoardingReady&&!slow.BoardingReady&&slow.PreparationRemaining==14,"same luggage trait has separate actual timers");slow.Copy().Validate();
  var sober=Make("Drunk","\"body.drunk\"",Row("type.Drunk.vomitPercent","0")+","+Row("type.Drunk.sleepPercent","0"));var drunk=Make("Drunk","\"body.drunk\"",Row("type.Drunk.vomitPercent","100")+","+Row("type.Drunk.sleepPercent","100"));ContentTuning.UseJson(baseline);var a=DrunkRideState.CreateAssignedDrunk("same",sober.Content);var b=DrunkRideState.CreateAssignedDrunk("same",drunk.Content);Check(!a.VomitPlanned&&!a.SleepPlanned&&b.VomitPlanned&&b.SleepPlanned,"independent drunk zero/100 plans");
  var text=Make("Food","\"item.food\"",Row("request.Quiet.reply.Accept","my reply")+","+Row("request.Quiet.unanswered","2")+","+Row("type.Food.intro.0","intro0")+","+Row("type.Food.intro.1","intro1")+","+Row("type.Food.intro.2","intro2"));Check(text.Dialogue.StartsWith("intro"),"type introduction reads rider text");var request=new PassengerRequest{Content=text.Content};request.Begin("trip",RequestKind.Quiet);request.Accept("dynamic");Check(request.SpokenLine("fallback")=="my reply","explicit rider reply replaces dynamic response");var unanswered=new PassengerRequest{Content=text.Content};unanswered.Begin("trip",RequestKind.Quiet);unanswered.ObserveOpportunity(true);Check(unanswered.Finish()==2,"unanswered penalty resolves per rider");
  var errand=Make("Errand","\"purpose.errand\"",Row("effect.errand.seconds","30"));var waiting=PassengerErrandState.Agree("trip","via","dest",errand.Content);waiting.Start(true);waiting.Advance(20,true,false);Check(waiting.Remaining==10&&!waiting.Completed,"individual errand actual wait");waiting.Validate();
  var legacy=ContentJson.Object(ContentJson.Parse(Profile(Wrap("Food","\"item.food\"",Row("choice.type.Food.1.immediate.satisfaction","3")))));legacy["schemaVersion"]=1d;ContentJson.Array(legacy["values"]).RemoveAll(o=>((string)ContentJson.Object(o)["id"]).StartsWith("choice.",StringComparison.Ordinal));legacy["contentHash"]=ContentTuning.ComputeHash(legacy);Reject(()=>ContentTuning.UseJson(ContentJson.Stringify(legacy)),"schema1 cannot silently ignore choice override");
  ContentTuning.UseJson(baseline);var inherited=Make("Food","\"item.food\"","");var changed=ContentJson.Object(ContentJson.Parse(ContentTuning.CaptureJson()));foreach(object o in ContentJson.Array(changed["values"])){var row=ContentJson.Object(o);if((string)row["id"]=="effect.food.crumbs")row["value"]="8";}changed["contentHash"]=ContentTuning.ComputeHash(changed);ContentTuning.UseJson(ContentJson.Stringify(changed));Check(inherited.Content.Int("effect.food.crumbs",-1)==8&&dry.Content.Int("effect.food.crumbs",-1)==2,"shared update affects inherited rows only");
  var sameText=ContentTuning.Text("request.Quiet.reply.Accept","fallback");var fixedText=new PassengerContent(new[]{new PassengerOverride{id="request.Quiet.reply.Accept",value=sameText}});Check(fixedText.OverrideText("request.Quiet.reply.Accept","dynamic-response")==sameText,"explicit same-as-default text is still fixed");
  ContentTuning.UseJson(baseline);Check(ContentTuning.CaptureJson()==baseline,"no global mutation after interleaving");
 }
}
